import type { ArgTypes } from '@storybook/web-components-vite';
import { nothing } from 'lit';
import { Directive, directive, PartType, type ElementPart, type PartInfo } from 'lit/directive.js';
import { action } from 'storybook/actions';
// Generated by @unframed/core's build ("npm run analyze -w @unframed/core").
import manifest from '../../../packages/core/custom-elements.json';
import { icons } from '../../../packages/core/src/internal/icons';

interface Typed {
  name: string;
  description?: string;
  type?: { text: string };
  default?: string;
}
interface Field extends Typed {
  kind: 'field' | 'method';
  privacy?: string;
  static?: boolean;
  readonly?: boolean;
  attribute?: string;
  parameters?: Typed[];
  return?: { type?: { text: string } };
}
interface Declaration {
  tagName?: string;
  members?: Field[];
  events?: Typed[];
  slots?: Typed[];
  cssProperties?: Typed[];
  cssParts?: Typed[];
}

const declarations = new Map<string, Declaration>(
  (manifest.modules as { declarations?: Declaration[] }[])
    .flatMap((module) => module.declarations ?? [])
    .filter((declaration) => declaration.tagName)
    .map((declaration) => [declaration.tagName!, declaration]),
);

const publicMembers = (tag: string, kind: Field['kind']) =>
  (declarations.get(tag)?.members ?? []).filter((m) => m.kind === kind && !m.static && m.privacy !== 'private' && m.privacy !== 'protected');

/** Type aliases from @unframed/core, spelled out so their controls can offer the values. */
const placements = ['top', 'top-start', 'top-end', 'bottom', 'bottom-start', 'bottom-end', 'left', 'right'];
const aliases: Record<string, string[]> = {
  AvatarSize: ['sm', 'md', 'lg', 'xl'],
  AvatarShape: ['circle', 'square'],
  AlertVariant: ['neutral', 'accent', 'info', 'success', 'warning', 'danger'],
  BadgeVariant: ['neutral', 'accent', 'info', 'success', 'warning', 'danger'],
  BadgeAppearance: ['soft', 'solid', 'outline'],
  BadgeSize: ['sm', 'md', 'lg'],
  ButtonVariant: ['primary', 'secondary', 'outline', 'ghost', 'danger', 'link'],
  ButtonSize: ['sm', 'md', 'lg'],
  ButtonType: ['button', 'submit', 'reset'],
  CardAppearance: ['outline', 'elevated', 'filled'],
  CardOrientation: ['vertical', 'horizontal'],
  DividerOrientation: ['horizontal', 'vertical'],
  SkeletonShape: ['text', 'rect', 'circle'],
  FieldSize: ['sm', 'md', 'lg'],
  PaginationSize: ['sm', 'md', 'lg'],
  ProgressSize: ['sm', 'md', 'lg'],
  ProgressVariant: ['accent', 'success', 'warning', 'danger'],
  SortDirection: ['ascending', 'descending'],
  TableDensity: ['comfortable', 'compact'],
  InputType: ['text', 'email', 'password', 'search', 'tel', 'url', 'number', 'date', 'time'],
  TextareaResize: ['none', 'vertical', 'auto'],
  Placement: placements,
  ToasterPlacement: ['top-start', 'top-center', 'top-end', 'bottom-start', 'bottom-center', 'bottom-end'],
  ToastVariant: ['neutral', 'accent', 'info', 'success', 'warning', 'danger'],
  BuiltInIconName: Object.keys(icons),
  // The full AutoFill type has hundreds of values: offer the common ones.
  AutoFill: ['off', 'on', 'name', 'email', 'username', 'current-password', 'new-password', 'one-time-code', 'tel', 'street-address', 'postal-code', 'country', 'bday'],
};

// `control: false` still shows a "Setup controls" link in the docs table; this doesn't.
const noControl = { disable: true } as const;

/** Example values for properties whose control is a JSON editor. */
const objectExamples: Record<string, string> = {
  'string[]': `["cheese", "olives"]`,
  'TableColumn[]': `[{ "key": "name", "label": "Name", "sortable": true }, { "key": "amount", "label": "Amount", "align": "end" }]`,
  'TableRow[]': `[{ "name": "John", "amount": 120 }, { "name": "Jane", "amount": 80 }]`,
};

/** The control for a TypeScript type from the manifest, ignoring `undefined` and `null`. */
function controlFor(typeText = ''): ArgTypes[string]['control'] & object {
  // Functions can't be edited in the panel; the stories show them in use.
  if (typeText.includes('=>')) return noControl as never;
  const parts = typeText
    .split('|')
    .map((part) => part.trim())
    .filter((part) => part && part !== 'undefined' && part !== 'null' && part !== '(string & {})');
  if (parts.length === 1 && parts[0] === 'boolean') return { type: 'boolean' };
  if (parts.length === 1 && parts[0] === 'number') return { type: 'number' };
  if (parts.length === 1 && parts[0] === 'string') return { type: 'text' };
  const options = parts.every((part) => /^'.*'$/.test(part)) ? parts.map((part) => part.slice(1, -1)) : parts.length === 1 ? aliases[parts[0]] : undefined;
  if (options) return { type: options.length <= 4 ? 'inline-radio' : 'select', options } as never;
  if (import.meta.env.DEV && !objectExamples[typeText]) console.warn(`[storybook] No control for the type "${typeText}". Add it to the aliases in .storybook/args.ts.`);
  return { type: 'object' };
}

/** Controls for CSS custom properties, with an example value in the description. */
function cssControl(name: string): { control: ArgTypes[string]['control']; example: string } {
  if (/(-bg|-color|-backdrop)(-|$)/.test(name)) {
    return {
      control: { type: 'color', presetColors: ['#6930c3', '#52b69a', '#0f766e', '#7c162e', '#f59e0b', '#111827', '#ffffff'] },
      example: name.endsWith('backdrop') ? 'rgb(0 0 0 / 0.7)' : '#0f766e',
    };
  }
  if (name.endsWith('font-weight')) return { control: { type: 'select', options: ['400', '500', '600', '700'] } as never, example: '600' };
  const examples: [RegExp, string][] = [
    [/font-family$/, 'Georgia, serif'],
    [/stroke-width$/, '1.5'],
    [/radius$/, '999px'],
    [/max-height$/, '10rem'],
    [/max-width$/, '20rem'],
    [/height$/, '3rem'],
    [/width$/, '24rem'],
    [/padding$/, '1.5rem'],
    [/(gap|indent|offset)$/, '2rem'],
    [/size$/, '1.5rem'],
  ];
  return { control: { type: 'text' }, example: examples.find(([pattern]) => pattern.test(name))?.[1] ?? '1rem' };
}

const summary = (text?: string) => (text ? { summary: text } : undefined);

/**
 * Builds the Controls and API tables from the manifest. Replaces Storybook's own
 * extraction, which keys everything by bare name: an attribute and a CSS part
 * both called `hint` overwrite each other there.
 *
 * Keys: attributes by attribute name, properties without one as `.name`
 * (like Lit's property binding), the rest as `slot:`, `event:`, `method:`
 * and `part:` names. CSS custom properties keep their `--` name.
 */
export function extractArgTypes(tag: unknown): ArgTypes {
  if (typeof tag !== 'string' || !declarations.has(tag)) return {};
  const declaration = declarations.get(tag)!;
  const argTypes: ArgTypes = {};

  for (const field of publicMembers(tag, 'field')) {
    const type = field.type?.text;
    const example = type && objectExamples[type];
    const common = {
      name: field.attribute ?? field.name,
      description: [
        field.description,
        field.attribute && field.attribute !== field.name && `Property: \`${field.name}\`.`,
        example && `Example: \`${example}\``,
      ]
        .filter(Boolean)
        .join('\n\n'),
      table: { type: summary(type), defaultValue: summary(field.default) },
    };
    if (field.attribute) {
      const control = controlFor(type);
      argTypes[field.attribute] = {
        ...common,
        // Sizes are a select everywhere, so they look the same in every story.
        control: field.attribute === 'size' && control && 'options' in control ? ({ ...control, type: 'select' } as never) : control,
        table: { ...common.table, category: 'attributes' },
      };
    } else {
      argTypes[`.${field.name}`] = {
        ...common,
        // Read-only properties (form, validity...) only report state.
        control: field.readonly ? noControl : controlFor(type),
        table: { ...common.table, category: 'properties' },
      };
    }
  }

  for (const method of publicMembers(tag, 'method')) {
    const params = (method.parameters ?? []).map((p) => `${p.name}${p.default ? '?' : ''}: ${p.type?.text ?? 'unknown'}`).join(', ');
    argTypes[`method:${method.name}`] = {
      name: `${method.name}()`,
      description: method.description,
      control: noControl,
      table: { category: 'methods', type: summary(`(${params}) => ${method.return?.type?.text ?? 'void'}`) },
    };
  }

  for (const event of declaration.events ?? []) {
    argTypes[`event:${event.name}`] = {
      name: event.name,
      description: `${event.description ?? ''} Logged in the Actions panel.`.trim(),
      control: noControl,
      table: { category: 'events', type: summary(event.type?.text) },
    };
  }

  for (const slot of declaration.slots ?? []) {
    argTypes[`slot:${slot.name || 'default'}`] = {
      name: slot.name || '(default)',
      description: slot.description,
      control: noControl,
      table: { category: 'slots' },
    };
  }

  for (const property of declaration.cssProperties ?? []) {
    const { control, example } = cssControl(property.name);
    argTypes[property.name] = {
      name: property.name,
      description: `${property.description ?? ''}\n\nExample: \`${example}\``,
      control,
      table: { category: 'css custom properties', defaultValue: summary(property.default) },
    };
  }

  for (const part of declaration.cssParts ?? []) {
    argTypes[`part:${part.name}`] = {
      name: part.name,
      description: `${part.description ?? ''}\n\nStyle it with \`${tag}::part(${part.name})\`.`,
      control: noControl,
      table: { category: 'css shadow parts' },
    };
  }

  // Storybook reads a control's choices from `options` on the arg type, not on the control.
  for (const argType of Object.values(argTypes)) {
    const control = argType.control as { options?: unknown[] } | undefined;
    if (control && typeof control === 'object' && control.options) argType.options ??= control.options;
  }

  return argTypes;
}

const isBooleanAttribute = (tag: string, attribute: string) =>
  publicMembers(tag, 'field').some((field) => field.attribute === attribute && field.type?.text === 'boolean');
const hasAttribute = (tag: string, attribute: string) => publicMembers(tag, 'field').some((field) => field.attribute === attribute);
const fieldOf = (tag: string, attribute: string) => publicMembers(tag, 'field').find((field) => field.attribute === attribute)?.name;

/**
 * Applies story args to the element it's on, using the keys from
 * `extractArgTypes`: attributes are set or removed, `.name` keys set properties,
 * `--` keys set custom properties inline. Other keys (story-only args) are
 * ignored. The element's events are logged in the Actions panel.
 *
 *   html`<uf-button ${spread(args)}>${args.text}</uf-button>`
 */
class SpreadDirective extends Directive {
  #applied = new Map<string, unknown>();
  #logged = new WeakSet<Element>();

  constructor(partInfo: PartInfo) {
    super(partInfo);
    if (partInfo.type !== PartType.ELEMENT) throw new Error('spread() goes on an element: <uf-button ${spread(args)}>');
  }

  render(_args: Record<string, unknown>) {
    return nothing;
  }

  override update(part: ElementPart, [args]: [Record<string, unknown>]) {
    const el = part.element as HTMLElement & Record<string, unknown>;
    const tag = el.localName;
    const set = new Map<string, unknown>();

    for (const [key, value] of Object.entries(args)) {
      if (value === undefined || value === null || value === '') continue;
      // Unchanged since the last render: don't reset what the user typed or toggled.
      if (this.#applied.get(key) === value) {
        set.set(key, value);
        continue;
      }
      if (key.startsWith('--')) {
        el.style.setProperty(key, String(value));
      } else if (key.startsWith('.')) {
        el[key.slice(1)] = value;
      } else if (hasAttribute(tag, key)) {
        if (isBooleanAttribute(tag, key)) el.toggleAttribute(key, value === true);
        // Objects and arrays (a table's columns and rows) go to the property, not the attribute.
        else if (typeof value === 'object') el[fieldOf(tag, key)!] = value;
        else el.setAttribute(key, String(value));
      } else {
        continue;
      }
      set.set(key, value);
    }
    // Args cleared in the Controls panel: undo what was set before.
    for (const key of this.#applied.keys()) {
      if (set.has(key)) continue;
      if (key.startsWith('--')) el.style.removeProperty(key);
      else if (!key.startsWith('.')) el.removeAttribute(key);
    }
    this.#applied = set;

    if (!this.#logged.has(el)) {
      this.#logged.add(el);
      for (const event of declarations.get(tag)?.events ?? []) {
        el.addEventListener(event.name, (e) => action(event.name)(e));
      }
    }
    return nothing;
  }
}

export const spread = directive(SpreadDirective);

/**
 * For a story about a subcomponent (`uf-checkbox-group` on the Checkbox page):
 * its controls, and only those, plus any story-only args.
 */
export function controlsOf(tag: string, ...storyArgs: string[]) {
  const argTypes = extractArgTypes(tag);
  return { argTypes, parameters: { controls: { include: [...Object.keys(argTypes), ...storyArgs] } } };
}

/** A story-only arg, like the text in a button's default slot. */
export const storyArg = (description: string, control: ArgTypes[string]['control'] = { type: 'text' }): ArgTypes[string] => ({
  control,
  description: `Story only: ${description}`,
  table: { category: 'story' },
});
